/*
 * A171457  Irregular triangle T(n, k) = coefficients of p(n, x), where p(n,
 *          x) = p(n-1, x)*Sum_{j=0..n-1} x^i - x*Sum_{j=0..binomial(n,2)-2}
 *          x^i, read by rows.
 * https://oeis.org/A171457
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   a(n) = coefficient of x^(k-1) in the polynomial p(k, x) that is
 *            generated by p(1,x) = 1, p(n,x) = p(n-1,x)*(1 + x + … + x^(n-1))
 *            – x*(1 + x + … + x^(binomial(n,2)-2)), read by rows (row 1 = 1,
 *            row 2 = 1,1, row 3 = 1,1,1,1, …)
 * Range:     u8 n <= 70, u16 n <= 147, u32 n <= 505, u64 n <= 1350,
 *            u128 n <= 1350, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

/* Sequences and indices are defined by the build system. */
seq_t a(idx_t n)
{
    /* rows[0] is row 1, rows[1] is row 2, etc. */
    static seq_t **rows      = NULL;
    static size_t *row_len   = NULL;  /* length of each row */
    static size_t *cum_len   = NULL;  /* cumulative length after each row */
    static size_t rows_cap   = 0;     /* allocated capacity for rows[]      */
    static size_t rows_size  = 0;     /* number of actually stored rows     */

    /* ---------- initialise the first row (row 1) if needed ---------- */
    if (rows_size == 0) {
        rows_cap = 4;
        rows      = (seq_t**)      malloc(rows_cap * sizeof(seq_t*));
        row_len   = (size_t*)      malloc(rows_cap * sizeof(size_t));
        cum_len   = (size_t*)      malloc(rows_cap * sizeof(size_t));

        rows[0]   = (seq_t*)      malloc(sizeof(seq_t));
        rows[0][0] = (seq_t)1;
        row_len[0] = 1;
        cum_len[0] = 1;
        rows_size  = 1;
    }

    /* ---------- ensure we have computed rows up to the index n ---------- */
    while (cum_len[rows_size - 1] < (size_t)n) {

        /* compute next row */
        idx_t next_row_nr = (idx_t)rows_size + 1;          /* 1‑based row number */
        size_t prev_len   = row_len[rows_size - 1];
        size_t new_len    = prev_len + (size_t)next_row_nr - 1;

        /* grow arrays to hold the new row */
        if (rows_size >= rows_cap) {
            size_t new_cap = rows_cap ? rows_cap * 2 : 4;
            while (new_cap < rows_size + 1) new_cap *= 2;

            rows     = (seq_t**)         realloc(rows,     new_cap * sizeof(seq_t*));
            row_len  = (size_t*)         realloc(row_len,  new_cap * sizeof(size_t));
            cum_len  = (size_t*)         realloc(cum_len,  new_cap * sizeof(size_t));
            rows_cap = new_cap;
        }

        seq_t *prev_row = rows[rows_size - 1];
        seq_t *new_row  = (seq_t*) malloc(new_len * sizeof(seq_t));

        /* convolution: multiply prev_row by a row of ones of length next_row_nr
           sliding window implementation */
        seq_t window = 0;
        for (size_t k = 0; k < new_len; ++k) {
            if (k < prev_len)                /* add new element to window */
                window += prev_row[k];
            if (k >= (size_t)next_row_nr)    /* remove oldest element */
                window -= prev_row[k - (size_t)next_row_nr];
            new_row[k] = window;
        }

        /* subtract the polynomial x*(1 + x + … + x^(bin - 2)) */
        idx_t bin   = next_row_nr * ((idx_t)next_row_nr - 1) / 2; /* binomial(n,2)   */
        idx_t sublen = bin - 1;                                 /* #terms to subtract */
        for (size_t k = 1; k <= (size_t)sublen && k < new_len; ++k)
            new_row[k] -= (seq_t)1;

        /* store the new row */
        rows[rows_size]      = new_row;
        row_len[rows_size]   = new_len;
        cum_len[rows_size]   = (rows_size == 0 ? new_len : cum_len[rows_size - 1] + new_len);
        ++rows_size;
    }

    /* ---------- locate the row that contains the requested index ---------- */
    size_t i = 0;
    while (cum_len[i] < (size_t)n) ++i;          /* first i such that cum_len[i] >= n */

    size_t prev_cum = (i == 0 ? 0 : cum_len[i - 1]);
    size_t offset   = (size_t)n - prev_cum - 1;   /* 0‑based index inside the row */

    return rows[i][offset];
}
